"""MNE-Python pipeline generated by eeglab2mne 0.3.0.

Source: erp_preprocessing.m
Steps: 9 exact, 6 approximate, 2 need manual work, 4 skipped.

Search for 'TODO' before running. See the migration report for why each
step is marked the way it is.
"""

import mne
import numpy as np
from mne_icalabel.iclabel import iclabel_label_components


# WARNING: ICA is refit in Python. Component order and signs will NOT match EEGLAB, so any hard-coded component numbers later in the script are meaningless. Re-select components (ICLabel or by eye), or run with --ica reuse to load EEGLAB's decomposition.

# --- L4: EEG = pop_loadset('filename', 'sub01.set', 'filepath', 'data/')  [exact]
raw = mne.io.read_raw_eeglab('data/sub01.set', preload=True)

# --- L5: EEG = pop_chanedit(EEG, 'lookup', 'standard_1005.elc')  [approximate]
# MNE 1.13 renamed 'standard_1005' to 'colin27_1005'; pick whichever exists
_template = next(m for m in ('colin27_1005', 'standard_1005')
                 if m in mne.channels.get_builtin_montages())
raw.set_montage(_template, on_missing='warn')

# --- L6: EEG = pop_select(EEG, 'nochannel', {'HEOG' 'VEOG'})  [exact]
raw.drop_channels(['HEOG', 'VEOG'])

# --- L7: EEG = pop_resample(EEG, 250)  [approximate]
raw.resample(250)

# --- L10: EEG = pop_eegfiltnew(EEG, 'locutoff', 1, 'hicutoff', 40, 'plotfreqz', 0)  [exact]
# Reproduce pop_eegfiltnew's design: one Hamming windowed-sinc filter whose order
# comes from the transition band, rounded up to even (firfilt plugin rules).
_fs = raw.info['sfreq']
_df = min(max(1 * 0.25, 2), min(1, _fs / 2 - 40))  # EEGLAB's default transition band (Hz)
_order = int(np.ceil(3.3 / (_df / _fs) / 2) * 2)
_df = 3.3 / _order * _fs  # transition band EEGLAB actually uses
raw.filter(l_freq=1, h_freq=40, l_trans_bandwidth=_df, h_trans_bandwidth=_df, filter_length=_order + 1, method='fir', fir_design='firwin', fir_window='hamming', phase='zero', pad='edge', skip_by_annotation=('edge', 'bad_acq_skip', 'boundary'))

# --- L11: EEG = pop_cleanline(EEG, 'linefreqs', [50 100], 'bandwidth', 2)  [approximate]
raw.notch_filter(freqs=[50, 100], method='spectrum_fit')

# --- L15: EEG = pop_clean_rawdata(EEG, 'FlatlineCriterion', 5, 'ChannelCriterion', 0.8, 'LineNoiseCriterion', 4, 'Highp…  [manual]
# TODO: EEG = pop_clean_rawdata(EEG, 'FlatlineCriterion', 5, 'ChannelCriterion', 0.8,      'LineNoiseCriterion', 4, 'Highpass', 'off', 'BurstCriterion', 20,      'WindowCriterion', 0.25, 'BurstRejection', 'on', 'Distance', 'Euclidian')
# clean_rawdata has no MNE equivalent. Options, from closest to simplest:
#   1. EEGPrep (2026): validated Python port of EEGLAB's default pipeline,
#      including clean_rawdata -- best if you need EEGLAB-equivalent numbers.
#   2. pyprep (bad channels) + asrpy (ASR bursts), mapped below.
#   3. mne.preprocessing.annotate_amplitude for simple flat/extreme segments.
#   flatlinecriterion=5: flat channels (s)  -> mne.preprocessing.annotate_amplitude(flat=...) / pyprep
#   channelcriterion=0.8: correlation-based bad channels -> pyprep.NoisyChannels.find_bad_by_correlation
#   linenoisecriterion=4: line-noise bad channels -> pyprep.NoisyChannels.find_bad_by_hfnoise
#   burstcriterion=20: Artifact Subspace Reconstruction -> asrpy.ASR(cutoff=...)
#   windowcriterion=0.25: bad-window removal -> mne annotations from a power threshold

# --- L18: EEG = pop_interp(EEG, originalEEG.chanlocs, 'spherical')  [manual]
# TODO: EEG = pop_interp(EEG, originalEEG.chanlocs, 'spherical')
# EEGLAB is restoring channels that were removed earlier (from a saved chanlocs).
# In MNE, keep the channels instead of dropping them: mark them in
# raw.info['bads'] where you removed them, then call:
# raw.interpolate_bads(reset_bads=True)

# --- L19: EEG = pop_reref(EEG, [])  [exact]
raw.set_eeg_reference('average', projection=False)

# --- L22: EEG = pop_runica(EEG, 'icatype', 'runica', 'extended', 1, 'interrupt', 'on')  [approximate]
ica = mne.preprocessing.ICA(n_components=None, method='infomax', fit_params=dict(extended=True), random_state=97, max_iter='auto')
ica.fit(raw)

# --- L23: EEG = pop_iclabel(EEG, 'default')  [approximate]
ic_proba = iclabel_label_components(raw, ica, inplace=True)  # (n_ics, 7)
ICLABEL_CLASSES = ['Brain', 'Muscle', 'Eye', 'Heart', 'Line Noise', 'Channel Noise', 'Other']

# --- L24: EEG = pop_icflag(EEG, [NaN NaN; 0.9 1; 0.9 1; NaN NaN; NaN NaN; NaN NaN; NaN NaN])  [exact]
icflag_thresholds = np.array([
    [np.nan, np.nan],
    [0.9, 1],
    [0.9, 1],
    [np.nan, np.nan],
    [np.nan, np.nan],
    [np.nan, np.nan],
    [np.nan, np.nan],
])  # rows: ICLABEL_CLASSES; [min max] probability
flagged = set()
for cls, (lo, hi) in enumerate(icflag_thresholds):
    if np.isnan(lo):
        continue
    hits = np.flatnonzero((ic_proba[:, cls] >= lo) & (ic_proba[:, cls] <= hi))
    flagged.update(int(i) for i in hits)
ica.exclude = sorted(set(ica.exclude) | flagged)
print(f'Flagged ICs (0-based): {ica.exclude}')

# --- L25: EEG = pop_subcomp(EEG, [], 0)  [exact]
ica.apply(raw)

# --- L29: EEG = pop_epoch(EEG, {'S  1' 'S  2'}, [-0.2 0.8], 'newname', 'sub01 epochs', 'epochinfo', 'yes')  [approximate]
events, event_id = mne.events_from_annotations(raw)
event_id = {k: v for k, v in event_id.items() if k in ['S  1', 'S  2']}
epochs = mne.Epochs(raw, events, event_id=event_id, tmin=-0.2, tmax=0.8, baseline=None, preload=True)

# --- L30: EEG = pop_rmbase(EEG, [-200 0], [])  [exact]
epochs.apply_baseline((-0.2, 0.0))

# --- L31: EEG = pop_eegthresh(EEG, 1, 1:30, -100, 100, -0.2, 0.796, 0, 1)  [exact]
data = epochs.get_data(picks=epochs.ch_names[0:30], tmin=-0.2, tmax=0.796) * 1e6  # V -> µV, EEGLAB thresholds are µV
bad = np.any((data < -100) | (data > 100), axis=(1, 2))
epochs.drop(np.flatnonzero(bad), reason='eeglab_threshold')

# --- L33: EEG = pop_saveset(EEG, 'filename', 'sub01_epochs.set', 'filepath', 'data/')  [exact]
epochs.save('sub01_epochs-epo.fif', overwrite=True)
# Or keep EEGLAB format: mne.export.export_raw/export_epochs(..., fmt='eeglab')
